#!/usr/bin/env bash
# A committed migration is never edited. Run in CI on every pull request:
#
#   build/check-migrations.sh origin/main
#
# Fails if this branch modifies, renames or deletes a migration the base branch already has.
# The model snapshot is regenerated by every new migration and is not checked.
set -euo pipefail

base="${1:-origin/main}"
since="$(git merge-base "$base" HEAD)"

edited="$(git diff --name-only --diff-filter=MRD "$since" HEAD -- '*/Migrations/*.cs' | grep -v 'ModelSnapshot\.cs$' || true)"

if [ -n "$edited" ]; then
  echo "These migrations were already on $base and must not change. Add a new migration instead:" >&2
  echo "$edited" >&2
  exit 1
fi

echo "No committed migration was edited."
